from pathlib import Path
r=Path(__file__).resolve().parents[2]
web=r/'flprog_bridge/esp32/web';dst=r/'flprog_bridge/esp32/FLProgBridgeEsp32/BridgeProjectPage.h'
codec=(web/'project_codec.js').read_text(encoding='utf-8-sig');runtime=(web/'project_viewer.js').read_text(encoding='utf-8-sig')
head='''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Веб из Flash ПЛК через ESP</title><style>body{font:17px system-ui;background:#101827;color:#eef;max-width:800px;margin:40px auto;padding:24px}progress{width:100%;height:26px}button{padding:12px}p{white-space:pre-line}</style><h1>Веб-проект из Flash ПЛК</h1><p id="load-status">Подключение…</p><progress id="load-progress" value="0" max="1"></progress><p>Передача порциями, проверка SHA-256 и распаковка в браузере. ESP не хранит весь проект в RAM и не пишет файловую систему.</p><button id="retry" hidden>Повторить загрузку</button>'''
html=head+'<script>'+codec.replace('</script','<\\/script')+'\n'+runtime.replace('</script','<\\/script')+'</script></html>'
dst.write_text('#pragma once\n// Generated by tests/build_project_viewer.py; no PLC/project data.\nstatic const char FLPROG_PROJECT_PAGE[] PROGMEM=R"FLPHTML('+html+')FLPHTML";\n',encoding='utf-8')
print('Generated universal project loader:',len(html.encode('utf-8')),'Flash bytes')
